# Izoverimlilik: W = n^2 hesap, ek yuk T_o = P*n (halo iletisimi), c=1
# E = W / (W + T_o) = 1 / (1 + P*n/n^2) = 1 / (1 + P/n)
def verimlilik(n, P):
    return 1.0 / (1.0 + P / n)

def gereken_n(P, E):
    return P * E / (1 - E)       # E = 1/(1+P/n) -> n = P*E/(1-E)

