P = 4

def cozumle(program, ad):
    # program[r] = islem listesi: ("send", hedef) / ("recv", kaynak)
    pc = [0] * P
    tamam = [False] * P
    ilerleme = True
    while ilerleme:
        ilerleme = False
        for r in range(P):
            if pc[r] >= len(program[r]):
                tamam[r] = True
                continue
            op, es = program[r][pc[r]]
            if op == "send":
                # eslesen recv hazir mi?
                if pc[es] < len(program[es]) and program[es][pc[es]] == ("recv", r):
                    pc[r] += 1
                    pc[es] += 1
                    ilerleme = True
            elif op == "recv":
                if pc[es] < len(program[es]) and program[es][pc[es]] == ("send", r):
                    pc[r] += 1
                    pc[es] += 1
                    ilerleme = True
    bekleyen = [r for r in range(P) if pc[r] < len(program[r])]
    print("%s -> ilerleyen adimlar: %s" % (ad, pc))
    if bekleyen:
        print("   OLU KILIT: bekleyen surecler %s" % bekleyen)
        for r in bekleyen:
            op, es = program[r][pc[r]]
            print("   surec %d, %s(%d) icin bekliyor" % (r, op, es))
    else:
        print("   tamamlandi, olu kilit yok")

