# G-Counter (buyume sayaci) CRDT: her dugum yalnizca kendi gozunu artirir, birlestirme = eleman bazli max
def birlestir(a, b):
    return {k: max(a.get(k, 0), b.get(k, 0)) for k in sorted(set(a) | set(b))}

def deger(s):
