import hashlib, bisect

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest()[:8], 16)

def halka(dugumler, vnode):
    noktalar = []
    for d in dugumler:
        for v in range(vnode):
            noktalar.append((h("%s#%d" % (d, v)), d))
    noktalar.sort()
    return [p[0] for p in noktalar], [p[1] for p in noktalar]

def ata(anahtarlar, dugumler, vnode):
    konum, sahip = halka(dugumler, vnode)
    return {k: sahip[bisect.bisect(konum, h(k)) % len(konum)] for k in anahtarlar}

