import random, math

def gossip(n, fanout, tohum):
    rng = random.Random(tohum)
    bilen = {0}
    tur = 0
    mesaj = 0
    while len(bilen) < n:
        tur += 1
        yeni = set()
        for d in bilen:
            for _ in range(fanout):
                hedef = rng.randrange(n)
                mesaj += 1
                if hedef not in bilen:
                    yeni.add(hedef)
        bilen |= yeni
        print("  tur %2d: bilen=%4d/%d" % (tur, len(bilen), n))
    return tur, mesaj

for n, f in [(1000, 1), (1000, 3)]:
    print("n=%d fanout=%d  (log2(n)=%.1f)" % (n, f, math.log2(n)))
    tur, mesaj = gossip(n, f, 1)
    print("  -> %d turda tamamlandi, %d mesaj, dugum basina %.1f mesaj" % (tur, mesaj, mesaj / n))
